stdout:
selinux=Enforcing
nginx_includes:
/etc/nginx/nginx.conf:11:include /usr/share/nginx/modules/*.conf;
/etc/nginx/nginx.conf:29:    include             /etc/nginx/mime.types;
/etc/nginx/nginx.conf:35:    include /etc/nginx/conf.d/*.conf;
/etc/nginx/nginx.conf:38:        listen       80;
/etc/nginx/nginx.conf:39:        listen       [::]:80;
/etc/nginx/nginx.conf:44:        include /etc/nginx/default.d/*.conf;
firewalld=active
8443_selinux_type=http_port_t                    tcp      80, 81, 443, 488, 8008, 8009, 8443, 9000

command:
set -eu
cat > /etc/nginx/conf.d/https-8443.conf <<'NGINX_CONF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1;

    ssl_certificate     /etc/nginx/tls/current/fullchain.pem;
    ssl_certificate_key /etc/nginx/tls/current/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:TLS:1m;

    location / {
        default_type text/plain;
        return 200 "node1 HTTPS certificate rotation is active\n";
    }
}
NGINX_CONF
cat > /etc/systemd/system/https-cert-renew.service <<'SERVICE_UNIT'
[Unit]
Description=Renew the nginx HTTPS certificate when it approaches expiry
After=local-fs.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/renew-https-certificate
SERVICE_UNIT
cat > /etc/systemd/system/https-cert-renew.timer <<'TIMER_UNIT'
[Unit]
Description=Check the nginx HTTPS certificate twice daily

[Timer]
OnCalendar=*-*-* 00,12:00:00
RandomizedDelaySec=30m
Persistent=true
Unit=https-cert-renew.service

[Install]
WantedBy=timers.target
TIMER_UNIT
restorecon -RF /etc/nginx /usr/local/sbin/renew-https-certificate /etc/systemd/system/https-cert-renew.service /etc/systemd/system/https-cert-renew.timer
/usr/sbin/nginx -t
systemctl daemon-reload
systemctl enable --now nginx.service https-cert-renew.timer
firewall-cmd --permanent --add-port=8443/tcp
firewall-cmd --reload

